def _backfill_audit_chain() -> None:
    """Hash-chain audit entries written before tamper evidence existed, oldest first, per organisation."""
    from app.services.audit import GENESIS, entry_hash

    bind = op.get_bind()
    rows = bind.execute(sa.text(
        "SELECT id, org_id, user_id, action, entity_type, entity_id, detail, ip, user_agent, at "
        "FROM audit_logs ORDER BY org_id NULLS FIRST, at, id")).mappings().all()
    heads: dict[str, tuple[int, str]] = {}
    for r in rows:
        key = str(r["org_id"]) if r["org_id"] else "system"
        seq, prev = heads.get(key, (0, GENESIS))
        entry = SimpleNamespace(**dict(r), seq=seq + 1, prev_hash=prev)
        h = entry_hash(entry)
        bind.execute(sa.text("UPDATE audit_logs SET seq = :s, prev_hash = :p, hash = :h WHERE id = :i"),
                     {"s": seq + 1, "p": prev, "h": h, "i": r["id"]})
        heads[key] = (seq + 1, h)
    for key, (seq, h) in heads.items():
        bind.execute(sa.text("INSERT INTO audit_chain_heads (chain_key, seq, hash) VALUES (:k, :s, :h)"),
                     {"k": key, "s": seq, "h": h})
